import 'dart:io';import 'package:flutter_test/flutter_test.dart';import 'package:surge_wizard/core/encounter_loader_v4.dart';import 'package:surge_wizard/core/headless_runner_v4.dart';void main(){test('same encounter seed reproduces telemetry',()async{final s=await File('assets/data/v4_vertical_slice_encounters.json').readAsString();final e=const EncounterLoaderV4().decode(s).first;const r=HeadlessRunnerV4();final a=r.run(encounter:e,seed:23092026),b=r.run(encounter:e,seed:23092026);expect(a.won,b.won);expect(a.activations,b.activations);});}
